#!/usr/bin/env python3
"""Play Codex notification sounds and monitor structured session errors."""

import base64
import ctypes
import json
import os
import platform
import signal
import subprocess
import sys
import tempfile
import time
from datetime import datetime
from pathlib import Path


CODEX_HOME = Path.home() / ".codex"
LOG_PATH = CODEX_HOME / "codex_ring.log"
WATCHER_PID_PATH = CODEX_HOME / "codex_ring_watcher.pid"
BACKGROUND_CREATION_FLAGS = (
    getattr(subprocess, "CREATE_NO_WINDOW", 0)
    | getattr(subprocess, "DETACHED_PROCESS", 0)
)
SOUND_BASE64 = {
    "complete": "",
    "permission": "",
    "retry": "",
}


def log_error(message: str) -> None:
    try:
        CODEX_HOME.mkdir(parents=True, exist_ok=True)
        with LOG_PATH.open("a", encoding="utf-8") as log_file:
            log_file.write(f"{datetime.now().isoformat()} {message}\n")
    except Exception:
        pass


def play_sound(sound_name: str) -> None:
    if sound_name not in SOUND_BASE64:
        raise ValueError(f"未知的音效类型: {sound_name}")
    subprocess.Popen(
        [sys.executable, str(Path(__file__).resolve()), "play-audio", sound_name],
        creationflags=BACKGROUND_CREATION_FLAGS,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        close_fds=True,
    )


def play_audio_sync(sound_name: str) -> None:
    audio_data = base64.b64decode(SOUND_BASE64[sound_name], validate=True)
    system = platform.system()
    if system == "Darwin":
        with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as audio_file:
            audio_file.write(audio_data)
            audio_path = Path(audio_file.name)
        try:
            subprocess.run(["afplay", str(audio_path)], check=False)
        finally:
            audio_path.unlink(missing_ok=True)
    elif system == "Windows":
        import winsound

        winsound.PlaySound(audio_data, winsound.SND_MEMORY)
    else:
        print("\a", end="", flush=True)


def parse_notify_payload() -> dict:
    raw_payload = sys.stdin.read().strip()
    if not raw_payload:
        raw_payload = sys.argv[-1] if len(sys.argv) > 1 else ""
    return json.loads(raw_payload)


def is_process_running(process_id: int) -> bool:
    try:
        os.kill(process_id, 0)
    except OSError:
        return False
    return True


def read_watcher_process_id() -> int | None:
    try:
        return int(WATCHER_PID_PATH.read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        return None


def start_error_watcher() -> None:
    process_id = read_watcher_process_id()
    if process_id and is_process_running(process_id):
        return

    subprocess.Popen(
        [sys.executable, str(Path(__file__).resolve()), "watch-errors"],
        creationflags=BACKGROUND_CREATION_FLAGS,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        close_fds=True,
    )


def stop_error_watcher() -> None:
    process_id = read_watcher_process_id()
    if process_id and is_process_running(process_id):
        if platform.system() == "Windows":
            process_handle = ctypes.windll.kernel32.OpenProcess(1, False, process_id)
            if not process_handle:
                raise OSError(f"无法打开监听器进程: {process_id}")
            try:
                if not ctypes.windll.kernel32.TerminateProcess(process_handle, 0):
                    raise OSError(f"无法终止监听器进程: {process_id}")
            finally:
                ctypes.windll.kernel32.CloseHandle(process_handle)
        else:
            os.kill(process_id, signal.SIGTERM)
    WATCHER_PID_PATH.unlink(missing_ok=True)


def is_error_event(line: str) -> bool:
    try:
        event = json.loads(line)
        return (
            event.get("type") == "event_msg"
            and event.get("payload", {}).get("type") == "error"
        )
    except json.JSONDecodeError:
        return False


def should_watcher_keep_alive(
    sessions_path: Path, timeout_seconds: int = 1800
) -> bool:
    """Keep the watcher alive while Codex sessions are being updated."""
    try:
        cutoff = time.time() - timeout_seconds
        return any(
            session_file.stat().st_mtime > cutoff
            for session_file in sessions_path.rglob("*.jsonl")
        )
    except OSError:
        return False


def watch_errors() -> None:
    WATCHER_PID_PATH.write_text(str(os.getpid()), encoding="utf-8")
    positions: dict[Path, int] = {}
    seen_events: set[str] = set()
    sessions_path = CODEX_HOME / "sessions"

    try:
        last_alive_check = time.time()
        while True:
            current_time = time.time()
            if current_time - last_alive_check >= 10:
                if not should_watcher_keep_alive(sessions_path):
                    return
                last_alive_check = current_time
            for session_file in sessions_path.rglob("*.jsonl"):
                position = positions.get(session_file)
                try:
                    with session_file.open("r", encoding="utf-8") as log_file:
                        if position is None:
                            log_file.seek(0, os.SEEK_END)
                        else:
                            log_file.seek(position)
                        while True:
                            last_position = log_file.tell()
                            line = log_file.readline()
                            if not line:
                                break
                            if not line.endswith("\n"):
                                log_file.seek(last_position)
                                break
                            if is_error_event(line) and line not in seen_events:
                                seen_events.add(line)
                                play_sound("retry")
                        positions[session_file] = log_file.tell()
                except OSError:
                    continue
            time.sleep(0.5)
    finally:
        if read_watcher_process_id() == os.getpid():
            WATCHER_PID_PATH.unlink(missing_ok=True)


def main() -> None:
    try:
        mode = sys.argv[1] if len(sys.argv) > 1 else "notify"
        if mode == "play-audio":
            play_audio_sync(sys.argv[2])
        elif mode == "permission":
            play_sound("permission")
        elif mode == "retry":
            play_sound("retry")
        elif mode == "start-error-watcher":
            start_error_watcher()
        elif mode == "stop-error-watcher":
            stop_error_watcher()
        elif mode == "watch-errors":
            watch_errors()
        else:
            payload = parse_notify_payload()
            if payload.get("type") == "agent-turn-complete":
                play_sound("complete")
    except Exception as error:
        log_error(f"{type(error).__name__}: {error}")


if __name__ == "__main__":
    main()
